import { Checkbox, cn, DensityProvider, Table, TableCaption, TableHead, TableHeader, TableRow, type TableDensity, useDensity, useI18n } from '@gntik-ai/ui';
import { useId, useRef, useState } from 'react';
import { PaginationFooter } from '../pagination-footer/PaginationFooter';
import { ColumnVisibilityMenu } from './column-menu';
import { clampColumnWidth, columnWidthOf, orderColumns, pinSideOf, setColumnPin, stickyTint, tableLayout, widthBounds, type ColumnWidths, type PinnedColumns } from './column-sizing';
import { DataTableBody, flattenBody, type DataTableBodyGroup } from './data-table-body';
import type { DataTableProps } from './data-table-props';
import { groupKeyOf, groupRows, paginate, selectionState, sortRows, toggleAll, toggleOne, type DataTableColumn, type DataTableGroupBy, type SortState } from './data-table-utils';
import { DensityToggle } from './density-toggle';
import { DEPLOYMENT_COLUMNS, DEPLOYMENT_ROWS } from './fixtures';
import { DataTableHeadCell } from './header-cell';
import { useControllable, useTableViews } from './use-table-views';
import { useVirtualRows } from './use-virtual-rows';
import { ViewSwitcher, type DataTableViewState } from './views';

export type { DataTableProps } from './data-table-props';

const defaultRowId = (row: unknown): string => {
  const id = (row as { id?: unknown }).id;
  return typeof id === 'string' || typeof id === 'number' ? String(id) : '';
};
const EMPTY_PINNED: PinnedColumns = {};
const EMPTY_WIDTHS: ColumnWidths = {};
const ROW_HEIGHT: Record<TableDensity, number> = { comfortable: 44, compact: 36 };

/**
 * Generic data table on the kit Table: typed columns, sortable headers (aria-sort), row selection
 * with select-all / indeterminate, column visibility menu, density toggle, row actions, loading
 * and empty states, client-side sort + pagination, optional collapsible row groups (`groupBy`),
 * column resize and pinning, row virtualization, inline cell editing and saved views.
 */
export function DataTable<T = (typeof DEPLOYMENT_ROWS)[number]>({
  rows = DEPLOYMENT_ROWS as unknown as readonly T[],
  columns = DEPLOYMENT_COLUMNS as unknown as ReadonlyArray<DataTableColumn<T>>,
  getRowId = defaultRowId,
  getRowLabel,
  caption = 'Deployments',
  showCaption = false,
  selectable = true,
  selectedIds,
  defaultSelectedIds = [],
  onSelectionChange,
  bulkActions,
  selectionSummary = true,
  rowActions,
  sort: sortProp,
  defaultSort = null,
  onSortChange,
  manualSorting = false,
  paginated = true,
  defaultPageSize = 10,
  pageSizeOptions = [10, 25, 50],
  density: densityProp,
  defaultDensity,
  onDensityChange,
  showDensityToggle = true,
  showColumnMenu = true,
  loading = false,
  loadingRows = 5,
  emptyState,
  groupBy,
  groupLabel,
  collapsibleGroups = true,
  collapsedGroups: collapsedProp,
  defaultCollapsedGroups = [],
  onCollapsedGroupsChange,
  onGroupByChange,
  hiddenColumns: hiddenProp,
  onHiddenColumnsChange,
  resizable = false,
  columnWidths: widthsProp,
  defaultColumnWidths = EMPTY_WIDTHS,
  onColumnWidthsChange,
  pinnedColumns: pinnedProp,
  defaultPinnedColumns = EMPTY_PINNED,
  onPinnedColumnsChange,
  showPinMenu,
  virtualize = 'auto',
  virtualizeThreshold = 100,
  rowHeight: rowHeightProp,
  virtualContainerClassName = 'max-h-[32rem]',
  onCellEdit,
  views: viewsProp,
  defaultViews,
  onViewsChange,
  activeViewId,
  defaultActiveViewId,
  onActiveViewChange,
  showViewSwitcher,
  filters,
  onFiltersChange,
  toolbar,
  className,
}: DataTableProps<T>) {
  const { t } = useI18n();
  const editHintId = useId();
  const tableRef = useRef<HTMLTableElement>(null);
  // A view active at mount seeds the initial state.
  const [initialView] = useState(() => (viewsProp ?? defaultViews ?? []).find((v) => v.id === (activeViewId ?? defaultActiveViewId)));
  const [initialFilters] = useState(() => filters);
  const seed = initialView?.state ?? {};
  const defaultHidden = columns.filter((c) => c.defaultHidden).map((c) => c.id);

  const [innerSort, setInnerSort] = useState<SortState | null>(seed.sort !== undefined ? seed.sort : defaultSort);
  const [innerSelected, setInnerSelected] = useState<ReadonlySet<string>>(() => new Set(defaultSelectedIds));
  const [innerDensity, setInnerDensity] = useState<TableDensity | null>(defaultDensity ?? null);
  const contextDensity = useDensity();
  const [hiddenList, setHiddenList] = useControllable<readonly string[]>(hiddenProp, () => seed.hiddenColumns ?? defaultHidden, (ids) => onHiddenColumnsChange?.([...ids]));
  const [widths, setWidths] = useControllable<ColumnWidths>(widthsProp, () => seed.columnWidths ?? defaultColumnWidths, (w) => onColumnWidthsChange?.({ ...w }));
  const [pinned, setPinned] = useControllable<PinnedColumns>(pinnedProp, () => seed.pinnedColumns ?? defaultPinnedColumns, onPinnedColumnsChange);
  // `undefined`: follow the groupBy prop; a string or null: set by a saved view.
  const [groupOverride, setGroupOverride] = useState<string | null | undefined>(seed.groupBy);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(defaultPageSize);

  const hidden: ReadonlySet<string> = new Set(hiddenList);
  const effectiveGroupBy: DataTableGroupBy<T> | undefined = groupOverride === undefined ? groupBy : ((groupOverride ?? undefined) as DataTableGroupBy<T> | undefined);
  const sort = sortProp === undefined ? innerSort : sortProp;
  const selected: ReadonlySet<string> = selectedIds ? new Set(selectedIds) : innerSelected;
  const density = densityProp ?? innerDensity ?? contextDensity;
  const visibleColumns = orderColumns(
    columns.filter((c) => !hidden.has(c.id)),
    pinned,
  );
  const labelOf =
    getRowLabel ??
    ((row: T) => {
      const first = columns[0];
      const value = first?.accessor?.(row);
      return value == null ? getRowId(row) : String(value);
    });

  const [innerCollapsed, setInnerCollapsed] = useState<ReadonlySet<string>>(() => new Set(defaultCollapsedGroups));
  const collapsed: ReadonlySet<string> = collapsedProp ? new Set(collapsedProp) : innerCollapsed;

  const sortedRows = manualSorting ? [...rows] : sortRows(rows, columns, sort);
  const allGroups = effectiveGroupBy ? groupRows(sortedRows, effectiveGroupBy, rows) : null;
  const sorted = allGroups ? allGroups.flatMap((g) => g.rows) : sortedRows;
  const pageRows = paginated ? paginate(sorted, page, pageSize) : sorted;
  // Rows in collapsed groups are hidden, so select-all leaves them alone.
  const pageIds = (effectiveGroupBy ? pageRows.filter((row) => !collapsed.has(groupKeyOf(row, effectiveGroupBy))) : pageRows).map(getRowId);
  const header = selectionState(pageIds, selected);
  const selectedList = rows.map(getRowId).filter((id) => selected.has(id));

  const setSelected = (next: Set<string>) => {
    setInnerSelected(next);
    onSelectionChange?.(rows.map(getRowId).filter((id) => next.has(id)));
  };
  const changeSort = (columnId: string, direction: SortState['direction']) => {
    const next: SortState = { columnId, direction: sort?.columnId === columnId ? direction : 'ascending' };
    setInnerSort(next);
    onSortChange?.(next);
    setPage(1);
  };
  const toggleGroup = (key: string) => {
    const next = new Set(collapsed);
    if (next.has(key)) next.delete(key);
    else next.add(key);
    setInnerCollapsed(next);
    onCollapsedGroupsChange?.([...next]);
  };
  const nameOf = (key: string) => key || 'No group';
  const bodyGroups: Array<DataTableBodyGroup<T>> | undefined =
    effectiveGroupBy && allGroups
      ? allGroups
          .map((g) => ({
            key: g.key,
            label: groupLabel ? groupLabel(g.key, g.rows) : nameOf(g.key),
            name: nameOf(g.key),
            rows: pageRows.filter((row) => groupKeyOf(row, effectiveGroupBy) === g.key),
            ids: g.rows.map(getRowId),
          }))
          .filter((g) => g.rows.length > 0)
      : undefined;
  const groupsForBody = bodyGroups && bodyGroups.length > 0 ? bodyGroups : undefined;

  const changeDensity = (next: TableDensity) => {
    setInnerDensity(next);
    onDensityChange?.(next);
  };
  const toggleColumn = (id: string, visible: boolean) => setHiddenList(visible ? hiddenList.filter((c) => c !== id) : [...hiddenList, id]);
  const resizeColumn = (column: DataTableColumn<T>, width: number) => setWidths({ ...widths, [column.id]: clampColumnWidth(column, width) });

  // Saved views.
  const groupName = (g: DataTableGroupBy<T> | undefined): string | null => (typeof g === 'string' ? g : null);
  const currentState: DataTableViewState = {
    filters,
    sort,
    hiddenColumns: hiddenList,
    columnWidths: widths,
    pinnedColumns: pinned,
    groupBy: groupOverride === undefined ? groupName(groupBy) : groupOverride,
  };
  const defaultState: DataTableViewState = {
    filters: initialFilters,
    sort: defaultSort,
    hiddenColumns: defaultHidden,
    columnWidths: defaultColumnWidths,
    pinnedColumns: defaultPinnedColumns,
    groupBy: groupName(groupBy),
  };
  const applyState = (state: DataTableViewState) => {
    const nextSort = state.sort ?? null;
    setInnerSort(nextSort);
    if (nextSort) onSortChange?.(nextSort);
    setHiddenList(state.hiddenColumns ?? defaultHidden);
    setWidths(state.columnWidths ?? defaultColumnWidths);
    setPinned(state.pinnedColumns ?? defaultPinnedColumns);
    const nextGroup = state.groupBy ?? null;
    setGroupOverride(nextGroup === groupName(groupBy) && typeof groupBy !== 'function' ? undefined : nextGroup);
    if (nextGroup !== currentState.groupBy) onGroupByChange?.(nextGroup);
    if (state.filters !== filters) onFiltersChange?.(state.filters);
    setPage(1);
  };
  const viewsApi = useTableViews({
    views: viewsProp,
    defaultViews,
    onViewsChange,
    activeViewId,
    defaultActiveViewId,
    onActiveViewChange,
    current: currentState,
    defaults: defaultState,
    apply: applyState,
  });
  const showViews = showViewSwitcher ?? (viewsProp != null || defaultViews != null || onViewsChange != null);

  const pinning = showPinMenu ?? (pinnedProp != null || defaultPinnedColumns !== EMPTY_PINNED || onPinnedColumnsChange != null);
  const layout = tableLayout({
    columns: visibleColumns,
    widths,
    pinned,
    sized: resizable || widthsProp != null || defaultColumnWidths !== EMPTY_WIDTHS,
    lead: selectable,
    trail: rowActions != null,
  });

  const items = loading || pageRows.length === 0 ? 0 : flattenBody(pageRows, groupsForBody, collapsed).length;
  const virtualOn = !loading && (virtualize === true || (virtualize === 'auto' && items > virtualizeThreshold));
  const rowHeight = rowHeightProp ?? ROW_HEIGHT[density];
  const virtual = useVirtualRows({ enabled: virtualOn, count: items, rowHeight, tableRef, viewportHeight: 512 });

  const hasSelection = selectable && selectedList.length > 0 && (selectionSummary || bulkActions != null);
  const showToolbar = toolbar != null || showDensityToggle || showColumnMenu || showViews || hasSelection;
  const anyEditable = onCellEdit != null && columns.some((c) => c.editable);

  return (
    <div className={cn('overflow-hidden rounded-xl border border-border bg-card shadow-sm', className)}>
      {showToolbar && (
        <div
          className={cn(
            'flex min-h-12 flex-wrap items-center gap-2 border-b border-border px-3 py-2 transition-colors motion-reduce:transition-none',
            hasSelection ? 'bg-primary/8' : 'bg-secondary/30',
          )}
        >
          <div className="flex min-w-0 flex-1 flex-wrap items-center gap-2">
            {hasSelection ? (
              <>
                {selectionSummary && (
                  <span className="text-[12.5px] font-semibold text-foreground" aria-live="polite">
                    {selectedList.length} selected
                  </span>
                )}
                {selectionSummary && bulkActions && <span aria-hidden className="h-4 w-px bg-border" />}
                {bulkActions?.(selectedList)}
              </>
            ) : (
              toolbar
            )}
          </div>
          <div className="flex items-center gap-2">
            {showViews && (
              <ViewSwitcher
                views={viewsApi.views}
                activeId={viewsApi.activeId}
                dirty={viewsApi.dirty}
                onSelect={viewsApi.select}
                onSaveAs={viewsApi.saveAs}
                onSave={viewsApi.save}
                onRename={viewsApi.rename}
                onDelete={viewsApi.remove}
                onReset={viewsApi.reset}
              />
            )}
            {showDensityToggle && <DensityToggle value={density} onChange={changeDensity} />}
            {showColumnMenu && (
              <ColumnVisibilityMenu
                columns={columns}
                hidden={hidden}
                onToggle={toggleColumn}
                pinOf={pinning ? (id) => pinSideOf(id, pinned) : undefined}
                onPin={pinning ? (id, side) => setPinned(setColumnPin(pinned, id, side)) : undefined}
              />
            )}
          </div>
        </div>
      )}
      {anyEditable && (
        <span id={editHintId} className="sr-only">
          Press Enter or F2 to edit.
        </span>
      )}
      {/* The toggle drives a density context for the table: its rows and the controls inside them. */}
      <DensityProvider density={density}>
        <Table
          ref={tableRef}
          aria-busy={loading || undefined}
          aria-rowcount={virtual ? items + 1 : undefined}
          stickyHeader={virtualOn}
          containerClassName={virtualOn ? virtualContainerClassName : undefined}
          containerLabel={virtualOn ? caption : undefined}
          className={layout.tableClassName}
          style={layout.tableStyle}
          data-virtualized={virtualOn || undefined}
        >
          <TableCaption srOnly={!showCaption}>{caption}</TableCaption>
          <TableHeader>
            <TableRow className="hover:bg-transparent" aria-rowindex={virtual ? 1 : undefined}>
              {selectable && (
                <TableHead
                  className={cn('w-10 pe-0', layout.lead.className, layout.lead.pinned && 'z-[11] bg-card', stickyTint(layout.lead, { head: true }))}
                  style={layout.lead.style}
                >
                  <Checkbox
                    aria-label={t('table.selectAllPage')}
                    checked={header.checked}
                    indeterminate={header.indeterminate}
                    disabled={loading || pageIds.length === 0}
                    onCheckedChange={() => setSelected(toggleAll(pageIds, selected))}
                  />
                </TableHead>
              )}
              {visibleColumns.map((c) => {
                const bounds = widthBounds(c);
                return (
                  <DataTableHeadCell
                    key={c.id}
                    column={c}
                    layout={layout.columns.get(c.id)}
                    sortDirection={sort?.columnId === c.id ? sort.direction : 'none'}
                    onSortChange={(dir) => changeSort(c.id, dir)}
                    resize={resizable && c.resizable !== false ? { width: columnWidthOf(c, widths), min: bounds.min, max: bounds.max, onResize: (w) => resizeColumn(c, w) } : undefined}
                  />
                );
              })}
              {rowActions && (
                <TableHead
                  className={cn('w-12', layout.trail.className, layout.trail.pinned && 'z-[11] bg-card', stickyTint(layout.trail, { head: true }))}
                  style={layout.trail.style}
                >
                  <span className="sr-only">{t('table.actions')}</span>
                </TableHead>
              )}
            </TableRow>
          </TableHeader>
          <DataTableBody
            rows={pageRows}
            columns={visibleColumns}
            getRowId={getRowId}
            getRowLabel={labelOf}
            selectable={selectable}
            selected={selected}
            onToggleRow={(id) => setSelected(toggleOne(id, selected))}
            rowActions={rowActions}
            loading={loading}
            loadingRows={loadingRows}
            emptyState={emptyState}
            groups={groupsForBody}
            collapsedGroups={collapsed}
            collapsibleGroups={collapsibleGroups}
            onToggleGroup={toggleGroup}
            onToggleGroupRows={(ids) => setSelected(toggleAll(ids, selected))}
            layout={layout}
            onCellEdit={onCellEdit}
            editHintId={anyEditable ? editHintId : undefined}
            virtual={virtual}
          />
        </Table>
      </DensityProvider>
      {loading && (
        <p role="status" className="sr-only">
          Loading {caption.toLowerCase()}…
        </p>
      )}
      {paginated && !loading && rows.length > 0 && (
        <PaginationFooter
          className="border-t border-border px-4 py-3"
          total={rows.length}
          page={page}
          onPageChange={setPage}
          pageSize={pageSize}
          onPageSizeChange={setPageSize}
          pageSizeOptions={pageSizeOptions}
          noun={caption}
        />
      )}
    </div>
  );
}

import { ChevronDown, Columns3 } from '@gntik-ai/icons';
import {
  Button,
  Menu,
  MenuCheckboxItem,
  MenuContent,
  MenuGroup,
  MenuGroupLabel,
  MenuRadioGroup,
  MenuRadioItem,
  MenuSeparator,
  MenuSub,
  MenuSubContent,
  MenuSubTrigger,
  MenuTrigger,
  useI18n,
} from '@gntik-ai/ui';
import type { PinSide } from './column-sizing';
import type { DataTableColumn } from './data-table-utils';

export interface ColumnVisibilityMenuProps<T> {
  columns: ReadonlyArray<DataTableColumn<T>>;
  hidden: ReadonlySet<string>;
  onToggle: (columnId: string, visible: boolean) => void;
  label?: string;
  /** Pin side of a column; with `onPin`, the menu gets a "Pin columns" section. */
  pinOf?: (columnId: string) => PinSide | null;
  onPin?: (columnId: string, side: PinSide | null) => void;
}

const PIN_NONE = 'none';

/**
 * "Columns" menu: one checkbox item per hideable column (the last visible column cannot be
 * hidden) and, when pinning is on, a submenu per visible column to pin it left, right or unpin it.
 */
export function ColumnVisibilityMenu<T>({ columns, hidden, onToggle, label: labelProp, pinOf, onPin }: ColumnVisibilityMenuProps<T>) {
  const { t } = useI18n();
  const label = labelProp ?? t('table.columns');
  const visibleCount = columns.filter((c) => !hidden.has(c.id)).length;
  const pinnable = onPin && pinOf ? columns.filter((c) => c.pinnable !== false && !hidden.has(c.id)) : [];
  return (
    <Menu>
      <MenuTrigger render={<Button variant="secondary" size="sm" icon={Columns3} trailingIcon={ChevronDown} />}>{label}</MenuTrigger>
      <MenuContent align="end" className="min-w-[200px]">
        <MenuGroup>
          <MenuGroupLabel>{t('table.visibleColumns')}</MenuGroupLabel>
          {columns
            .filter((c) => c.hideable !== false)
            .map((c) => {
              const visible = !hidden.has(c.id);
              return (
                <MenuCheckboxItem key={c.id} checked={visible} disabled={visible && visibleCount <= 1} onCheckedChange={(on) => onToggle(c.id, on)}>
                  {c.header}
                </MenuCheckboxItem>
              );
            })}
        </MenuGroup>
        {pinnable.length > 0 && onPin && pinOf && (
          <>
            <MenuSeparator />
            <MenuGroup>
              <MenuGroupLabel>Pin columns</MenuGroupLabel>
              {pinnable.map((c) => {
                const side = pinOf(c.id);
                return (
                  <MenuSub key={c.id}>
                    <MenuSubTrigger>
                      {c.header}
                      {side && <span className="ms-auto ps-3 text-[11.5px] text-muted-foreground">{side === 'left' ? 'Left' : 'Right'}</span>}
                    </MenuSubTrigger>
                    <MenuSubContent>
                      <MenuRadioGroup
                        value={side ?? PIN_NONE}
                        onValueChange={(v: unknown) => onPin(c.id, v === 'left' || v === 'right' ? v : null)}
                      >
                        <MenuRadioItem value="left">Pin left</MenuRadioItem>
                        <MenuRadioItem value="right">Pin right</MenuRadioItem>
                        <MenuRadioItem value={PIN_NONE}>Unpinned</MenuRadioItem>
                      </MenuRadioGroup>
                    </MenuSubContent>
                  </MenuSub>
                );
              })}
            </MenuGroup>
          </>
        )}
      </MenuContent>
    </Menu>
  );
}

import type { CSSProperties } from 'react';
import type { DataTableColumn } from './data-table-utils';

/** Column widths in px by column id. */
export type ColumnWidths = Readonly<Record<string, number>>;

/** Columns pinned to the start (left in LTR) and end edges, in display order. */
export interface PinnedColumns {
  left?: readonly string[];
  right?: readonly string[];
}

export type PinSide = 'left' | 'right';

export const DEFAULT_COLUMN_WIDTH = 160;
export const MIN_COLUMN_WIDTH = 60;
export const MAX_COLUMN_WIDTH = 640;
/** Width of the selection (checkbox) and row-actions columns: `w-10` and `w-12`. */
export const LEAD_WIDTH = 40;
export const TRAIL_WIDTH = 48;

/** Width limits of a column. */
export function widthBounds<T>(column: DataTableColumn<T>): { min: number; max: number } {
  const min = column.minWidth ?? MIN_COLUMN_WIDTH;
  return { min, max: Math.max(min, column.maxWidth ?? MAX_COLUMN_WIDTH) };
}

/** Clamps a width to the column's limits (rounded to whole px). */
export function clampColumnWidth<T>(column: DataTableColumn<T>, width: number): number {
  const { min, max } = widthBounds(column);
  return Math.round(Math.min(max, Math.max(min, width)));
}

/** Effective width of a column: the widths map, then `column.width`, then the default. */
export function columnWidthOf<T>(column: DataTableColumn<T>, widths: ColumnWidths): number {
  return clampColumnWidth(column, widths[column.id] ?? column.width ?? DEFAULT_COLUMN_WIDTH);
}

export function pinSideOf(id: string, pinned: PinnedColumns): PinSide | null {
  if (pinned.left?.includes(id)) return 'left';
  if (pinned.right?.includes(id)) return 'right';
  return null;
}

/** Pins a column to a side (appended to that side) or unpins it (`null`). */
export function setColumnPin(pinned: PinnedColumns, id: string, side: PinSide | null): PinnedColumns {
  const left = (pinned.left ?? []).filter((c) => c !== id);
  const right = (pinned.right ?? []).filter((c) => c !== id);
  if (side === 'left') left.push(id);
  if (side === 'right') right.push(id);
  return { left, right };
}

/** Display order: start-pinned columns (pin order), unpinned columns (column order), end-pinned columns. */
export function orderColumns<T>(columns: ReadonlyArray<DataTableColumn<T>>, pinned: PinnedColumns): Array<DataTableColumn<T>> {
  const byId = new Map(columns.map((c) => [c.id, c]));
  const pick = (ids: readonly string[] = []) => ids.map((id) => byId.get(id)).filter((c): c is DataTableColumn<T> => c != null);
  const left = pick(pinned.left);
  const right = pick(pinned.right);
  const taken = new Set([...left, ...right].map((c) => c.id));
  return [...left, ...columns.filter((c) => !taken.has(c.id)), ...right];
}

/** Layout of one column cell: inline style (width, sticky offset) and classes. */
export interface CellLayout {
  style?: CSSProperties;
  className?: string;
  pinned?: PinSide;
}

export interface TableLayout {
  /** Layout per column id. */
  columns: ReadonlyMap<string, CellLayout>;
  /** Selection column (sticky at the start when any column is start-pinned). */
  lead: CellLayout;
  /** Row-actions column (sticky at the end when any column is end-pinned). */
  trail: CellLayout;
  /** Table classes and style (fixed layout and total width when columns are sized). */
  tableClassName?: string;
  tableStyle?: CSSProperties;
}

// Sticky cells need an opaque surface; the row tint (hover, selected) is layered under the content.
const STICKY = 'sticky z-[1] bg-card';
const START_EDGE = 'border-e border-border';
const END_EDGE = 'border-s border-border';

/**
 * Computes widths and sticky offsets. With `sized` off and nothing pinned the table keeps its
 * automatic layout (the original behaviour); otherwise it switches to a fixed layout whose width
 * is the sum of the column widths (at least the container's).
 */
export function tableLayout<T>({
  columns,
  widths,
  pinned,
  sized,
  lead,
  trail,
}: {
  columns: ReadonlyArray<DataTableColumn<T>>;
  widths: ColumnWidths;
  pinned: PinnedColumns;
  sized: boolean;
  lead: boolean;
  trail: boolean;
}): TableLayout {
  const map = new Map<string, CellLayout>();
  const hasStart = columns.some((c) => pinSideOf(c.id, pinned) === 'left');
  const hasEnd = columns.some((c) => pinSideOf(c.id, pinned) === 'right');
  const active = sized || hasStart || hasEnd;
  if (!active) {
    for (const c of columns) map.set(c.id, {});
    return { columns: map, lead: {}, trail: {} };
  }
  const widthOf = (c: DataTableColumn<T>) => columnWidthOf(c, widths);
  const fixed = (w: number): CSSProperties => ({ width: w, minWidth: w, maxWidth: w });

  let start = lead ? LEAD_WIDTH : 0;
  const startIds = columns.filter((c) => pinSideOf(c.id, pinned) === 'left');
  startIds.forEach((c, i) => {
    const w = widthOf(c);
    map.set(c.id, {
      pinned: 'left',
      style: { ...fixed(w), insetInlineStart: start },
      className: [STICKY, i === startIds.length - 1 && START_EDGE].filter(Boolean).join(' '),
    });
    start += w;
  });
  let end = trail ? TRAIL_WIDTH : 0;
  const endIds = columns.filter((c) => pinSideOf(c.id, pinned) === 'right');
  [...endIds].reverse().forEach((c, i) => {
    const w = widthOf(c);
    map.set(c.id, {
      pinned: 'right',
      style: { ...fixed(w), insetInlineEnd: end },
      className: [STICKY, i === endIds.length - 1 && END_EDGE].filter(Boolean).join(' '),
    });
    end += w;
  });
  for (const c of columns) if (!map.has(c.id)) map.set(c.id, { style: fixed(widthOf(c)) });

  const total = columns.reduce((sum, c) => sum + widthOf(c), 0) + (lead ? LEAD_WIDTH : 0) + (trail ? TRAIL_WIDTH : 0);
  return {
    columns: map,
    lead: hasStart ? { pinned: 'left', style: { insetInlineStart: 0 }, className: STICKY } : {},
    trail: hasEnd ? { pinned: 'right', style: { insetInlineEnd: 0 }, className: STICKY } : {},
    tableClassName: 'table-fixed',
    tableStyle: { width: total, minWidth: '100%' },
  };
}

/** Under-content tint for sticky cells of a hovered or selected row (and the header surface). */
export function stickyTint(layout: CellLayout | undefined, { selected = false, head = false } = {}): string | undefined {
  if (!layout?.pinned) return undefined;
  const base = 'before:pointer-events-none before:absolute before:inset-0 before:-z-10';
  if (head) return `${base} before:bg-secondary/30`;
  return `${base} ${selected ? 'before:bg-primary/8' : '[tr:hover>&]:before:bg-accent/30'}`;
}

import { Inbox } from '@gntik-ai/icons';
import { cn, EmptyState, Skeleton, TableBody, TableCell, TableRow, useI18n } from '@gntik-ai/ui';
import type { ReactNode } from 'react';
import { columnAlign } from './data-table-utils';
import { DataTableRow, GroupHeaderRow, type DataTableBodyGroup, type RowContext } from './data-table-row';
import type { VirtualWindow } from './use-virtual-rows';

export type { DataTableBodyGroup } from './data-table-row';

export interface DataTableBodyProps<T> extends RowContext<T> {
  rows: readonly T[];
  loading: boolean;
  loadingRows: number;
  emptyState?: ReactNode;
  /** Grouped rendering: one `<tbody>` per group with a header row (replaces `rows`). */
  groups?: ReadonlyArray<DataTableBodyGroup<T>>;
  /** Keys of collapsed groups. */
  collapsedGroups?: ReadonlySet<string>;
  /** Group headers render a collapse button (default true). */
  collapsibleGroups?: boolean;
  onToggleGroup?: (key: string) => void;
  /** Selects or clears every row of a group. */
  onToggleGroupRows?: (ids: readonly string[]) => void;
  /** Renders only the items of this window (virtualized rows), with spacers for the rest. */
  virtual?: VirtualWindow;
}

/** One rendered line of the body: a group header or a data row. */
export type DataTableBodyItem<T> = { kind: 'group'; group: DataTableBodyGroup<T>; open: boolean } | { kind: 'row'; row: T; groupKey?: string };

/** Flattens rows (or groups and their open rows) into the lines the body renders. */
export function flattenBody<T>(rows: readonly T[], groups: ReadonlyArray<DataTableBodyGroup<T>> | undefined, collapsed: ReadonlySet<string> | undefined): Array<DataTableBodyItem<T>> {
  if (!groups) return rows.map((row) => ({ kind: 'row', row }));
  const items: Array<DataTableBodyItem<T>> = [];
  for (const group of groups) {
    const open = !collapsed?.has(group.key);
    items.push({ kind: 'group', group, open });
    if (open) for (const row of group.rows) items.push({ kind: 'row', row, groupKey: group.key });
  }
  return items;
}

function Spacer({ height, span }: { height: number; span: number }) {
  if (height <= 0) return null;
  return (
    <tbody aria-hidden data-virtual-spacer="">
      <tr role="presentation">
        <td colSpan={span} style={{ height, padding: 0, border: 0 }} />
      </tr>
    </tbody>
  );
}

/** Body rows, plus the loading (skeleton rows) and empty (EmptyState) states. */
export function DataTableBody<T>(props: DataTableBodyProps<T>) {
  const { rows, columns, selectable, selected, rowActions, loading, loadingRows, emptyState, groups, collapsedGroups, collapsibleGroups = true, onToggleGroup, onToggleGroupRows, virtual } = props;
  const { t } = useI18n();
  const span = columns.length + (selectable ? 1 : 0) + (rowActions ? 1 : 0);
  if (loading) {
    return (
      <TableBody>
        {Array.from({ length: loadingRows }, (_, i) => (
          <TableRow key={`loading-${i}`}>
            {selectable && (
              <TableCell className="w-10">
                <Skeleton className="size-4 rounded-[4px]" />
              </TableCell>
            )}
            {columns.map((c) => (
              <TableCell key={c.id} align={columnAlign(c)}>
                <Skeleton className={cn('h-3.5', columnAlign(c) === 'right' ? 'ms-auto w-16' : 'w-24')} />
              </TableCell>
            ))}
            {rowActions && <TableCell className="w-12" />}
          </TableRow>
        ))}
      </TableBody>
    );
  }
  if (rows.length === 0) {
    return (
      <TableBody>
        <TableRow className="hover:bg-transparent">
          <TableCell colSpan={span} className="py-10">
            {emptyState ?? <EmptyState icon={Inbox} size="sm" title={t('common.noResults')} description={t('table.emptyDescription')} />}
          </TableCell>
        </TableRow>
      </TableBody>
    );
  }
  const row = (r: T, extra?: { ariaRowIndex?: number; height?: number }) => (
    <DataTableRow key={props.getRowId(r)} {...props} row={r} ariaRowIndex={extra?.ariaRowIndex} style={extra?.height ? { height: extra.height } : undefined} />
  );
  const header = (group: DataTableBodyGroup<T>, open: boolean, extra?: { ariaRowIndex?: number; height?: number }) => (
    <GroupHeaderRow
      key={`group-${group.key}`}
      group={group}
      open={open}
      selectable={selectable}
      selected={selected}
      span={span - (selectable ? 1 : 0)}
      collapsible={collapsibleGroups}
      onToggle={onToggleGroup}
      onToggleRows={onToggleGroupRows}
      ariaRowIndex={extra?.ariaRowIndex}
      style={extra?.height ? { height: extra.height } : undefined}
    />
  );

  if (virtual) {
    const items = flattenBody(rows, groups, collapsedGroups);
    const { start, end, rowHeight } = virtual;
    // Consecutive items of the same group share a <tbody> (a rowgroup), as in the full render.
    const chunks: Array<{ key: string; group?: string; items: Array<{ item: DataTableBodyItem<T>; index: number }> }> = [];
    for (let i = start; i < Math.min(end, items.length); i++) {
      const item = items[i]!;
      const g = item.kind === 'group' ? item.group.key : item.groupKey;
      const lastChunk = chunks[chunks.length - 1];
      if (lastChunk && lastChunk.group === g) lastChunk.items.push({ item, index: i });
      else chunks.push({ key: `${g ?? 'rows'}-${i}`, group: g, items: [{ item, index: i }] });
    }
    return (
      <>
        <Spacer height={start * rowHeight} span={span} />
        {chunks.map((chunk) => (
          <TableBody key={chunk.key} data-group={chunk.group}>
            {chunk.items.map(({ item, index }) =>
              item.kind === 'group'
                ? header(item.group, item.open, { ariaRowIndex: index + 2, height: rowHeight })
                : row(item.row, { ariaRowIndex: index + 2, height: rowHeight }),
            )}
          </TableBody>
        ))}
        <Spacer height={Math.max(0, items.length - end) * rowHeight} span={span} />
      </>
    );
  }

  if (!groups) return <TableBody>{rows.map((r) => row(r))}</TableBody>;
  return (
    <>
      {groups.map((group, gi) => {
        const open = !collapsedGroups?.has(group.key);
        return (
          <TableBody
            key={group.key}
            data-group={group.key}
            // Every group but the last keeps the bottom rule of its last row.
            className={gi < groups.length - 1 ? '[&>tr:last-child>td]:border-b' : undefined}
          >
            {header(group, open)}
            {open && group.rows.map((r) => row(r))}
          </TableBody>
        );
      })}
    </>
  );
}

import type { MoreMenuAction, TableDensity } from '@gntik-ai/ui';
import type { ReactNode } from 'react';
import type { ColumnWidths, PinnedColumns } from './column-sizing';
import type { DataTableColumn, DataTableGroupBy, SortState } from './data-table-utils';
import type { DataTableCellEditHandler } from './editable-cell';
import type { DataTableView } from './views';

export interface DataTableProps<T> {
  rows?: readonly T[];
  columns?: ReadonlyArray<DataTableColumn<T>>;
  /** Stable row id (defaults to `row.id`). */
  getRowId?: (row: T) => string;
  /** Row name for checkbox and menu labels (defaults to the first column's value). */
  getRowLabel?: (row: T) => string;
  /** Table name (screen-reader caption unless `showCaption`). */
  caption?: string;
  showCaption?: boolean;

  /** Row selection with a select-all header checkbox (current page). */
  selectable?: boolean;
  selectedIds?: readonly string[];
  defaultSelectedIds?: readonly string[];
  onSelectionChange?: (ids: string[]) => void;
  /** Rendered in the toolbar while rows are selected. */
  bulkActions?: (selectedIds: string[]) => ReactNode;
  /**
   * Shows the "N selected" text in the toolbar while rows are selected (default true). Turn it
   * off when the page renders its own count, e.g. a BulkActionBar.
   */
  selectionSummary?: boolean;

  /** Row-actions menu items. */
  rowActions?: (row: T) => Array<MoreMenuAction | 'separator'>;

  sort?: SortState | null;
  defaultSort?: SortState | null;
  onSortChange?: (sort: SortState) => void;
  /** Rows arrive sorted (server side): headers still toggle, rows are not re-sorted. */
  manualSorting?: boolean;

  /** Client-side pagination; false shows every row. */
  paginated?: boolean;
  defaultPageSize?: number;
  pageSizeOptions?: readonly number[];

  /** Controlled row density. */
  density?: TableDensity;
  /** Initial density; omitted, the table follows the surrounding DensityProvider (comfortable outside one). */
  defaultDensity?: TableDensity;
  onDensityChange?: (density: TableDensity) => void;
  showDensityToggle?: boolean;
  showColumnMenu?: boolean;

  loading?: boolean;
  loadingRows?: number;
  emptyState?: ReactNode;
  /**
   * Groups rows under header rows (a field key or a function returning the group key). Groups keep
   * the order in which their keys first appear in `rows`; sorting applies inside each group, and
   * pagination pages through the grouped rows (each header shows the group's full count).
   */
  groupBy?: DataTableGroupBy<T>;
  /** Header text of a group (default: the key, or "No group" for rows without a value). */
  groupLabel?: (key: string, rows: readonly T[]) => ReactNode;
  /** Group headers render a keyboard-accessible collapse button (default true). */
  collapsibleGroups?: boolean;
  /** Controlled collapsed group keys. */
  collapsedGroups?: readonly string[];
  /** Group keys collapsed initially. */
  defaultCollapsedGroups?: readonly string[];
  onCollapsedGroupsChange?: (keys: string[]) => void;

  /** Called when a saved view switches grouping (a field key, or `null` for none). */
  onGroupByChange?: (groupBy: string | null) => void;

  /** Controlled hidden column ids (default: columns with `defaultHidden`). */
  hiddenColumns?: readonly string[];
  onHiddenColumnsChange?: (ids: string[]) => void;

  /** Resize handles on the column headers (pointer drag, or arrow keys on the focused handle). */
  resizable?: boolean;
  /** Controlled column widths in px by column id. */
  columnWidths?: ColumnWidths;
  defaultColumnWidths?: ColumnWidths;
  onColumnWidthsChange?: (widths: Record<string, number>) => void;

  /** Controlled pinned columns (sticky at the start or end edge while scrolling sideways). */
  pinnedColumns?: PinnedColumns;
  defaultPinnedColumns?: PinnedColumns;
  onPinnedColumnsChange?: (pinned: PinnedColumns) => void;
  /** Pin / unpin from the column menu (default true when pinning is in use: a pinned prop or callback). */
  showPinMenu?: boolean;

  /**
   * Renders only the rows in view (plus overscan) inside a scrolling body with a sticky header.
   * `'auto'` (default) turns it on above `virtualizeThreshold` rendered rows (with pagination,
   * the rows of the current page). The table exposes `aria-rowcount` and each row its
   * `aria-rowindex`; selection (select-all covers every row) and grouping keep working.
   * Limits: rows get a fixed height (`rowHeight`), so multi-line cells are clipped; a row that
   * scrolls out of view unmounts, so focus inside it (or an open inline editor) is lost; a group's
   * header row renders only while it is in view.
   */
  virtualize?: boolean | 'auto';
  virtualizeThreshold?: number;
  /** Row height in px for virtualization (default by density: 44 comfortable, 36 compact). */
  rowHeight?: number;
  /** Classes of the virtualized scroll container: its max height (default `max-h-[32rem]`). */
  virtualContainerClassName?: string;

  /**
   * Inline editing of `editable` columns. Return nothing to accept (and update `rows`), or a
   * message (or throw) to reject: the message is shown inline under the editor.
   */
  onCellEdit?: DataTableCellEditHandler<T>;

  /** Saved views (controlled). Each captures filters, sort, visible columns, widths, pinning and grouping. */
  views?: readonly DataTableView[];
  defaultViews?: readonly DataTableView[];
  onViewsChange?: (views: DataTableView[]) => void;
  activeViewId?: string | null;
  defaultActiveViewId?: string | null;
  onActiveViewChange?: (id: string | null) => void;
  /** Shows the view switcher (default: when views are in use). */
  showViewSwitcher?: boolean;
  /** Opaque filter state of the page's toolbar, saved with views. */
  filters?: unknown;
  /** Called when a view (or a reset) restores filters. */
  onFiltersChange?: (filters: unknown) => void;

  /** Left side of the toolbar (title, search, FilterBar…). */
  toolbar?: ReactNode;
  className?: string;
}

import { ChevronRight } from '@gntik-ai/icons';
import { Checkbox, cn, MoreMenu, TableCell, TableHead, TableRow, type MoreMenuAction, useI18n } from '@gntik-ai/ui';
import type { CSSProperties, ReactNode } from 'react';
import { stickyTint, type TableLayout } from './column-sizing';
import { COLUMN_VARIANT_CLASSES, columnAlign, formatCell, selectionState, type DataTableColumn } from './data-table-utils';
import { EditableCell, isCellEditable, type DataTableCellEditHandler } from './editable-cell';

/** A group as the body renders it: its rows on the current page plus header data. */
export interface DataTableBodyGroup<T> {
  key: string;
  /** Visible group name (header text). */
  label: ReactNode;
  /** Plain-text name for button and checkbox labels. */
  name: string;
  /** Rows of the group on the current page. */
  rows: readonly T[];
  /** Ids of every row in the group (all pages): the count and the group checkbox use them. */
  ids: readonly string[];
}

/** Row rendering shared by the plain, grouped and virtualized bodies. */
export interface RowContext<T> {
  columns: ReadonlyArray<DataTableColumn<T>>;
  getRowId: (row: T) => string;
  getRowLabel: (row: T) => string;
  selectable: boolean;
  selected: ReadonlySet<string>;
  onToggleRow: (id: string) => void;
  rowActions?: (row: T) => Array<MoreMenuAction | 'separator'>;
  layout?: TableLayout;
  onCellEdit?: DataTableCellEditHandler<T>;
  /** Id of the "Press Enter or F2 to edit" hint. */
  editHintId?: string;
}

export interface DataTableRowProps<T> extends RowContext<T> {
  row: T;
  /** 1-based row index in the whole table (virtualized tables). */
  ariaRowIndex?: number;
  style?: CSSProperties;
}

export function DataTableRow<T>({
  row,
  columns,
  getRowId,
  getRowLabel,
  selectable,
  selected,
  onToggleRow,
  rowActions,
  layout,
  onCellEdit,
  editHintId,
  ariaRowIndex,
  style,
}: DataTableRowProps<T>) {
  const { t } = useI18n();
  const id = getRowId(row);
  const isSelected = selected.has(id);
  const label = getRowLabel(row);
  const tint = (l: TableLayout['lead'] | undefined) => stickyTint(l, { selected: selectable && isSelected });
  return (
    <TableRow selected={selectable && isSelected} aria-rowindex={ariaRowIndex} data-row-id={id} style={style}>
      {selectable && (
        <TableCell className={cn('w-10 pe-0', layout?.lead.className, tint(layout?.lead))} style={layout?.lead.style}>
          <Checkbox aria-label={t('table.selectRow', { label })} checked={isSelected} onCheckedChange={() => onToggleRow(id)} />
        </TableCell>
      )}
      {columns.map((c) => {
        const cl = layout?.columns.get(c.id);
        const content = c.cell ? c.cell(row) : formatCell(c.accessor?.(row));
        const editable = onCellEdit && editHintId && isCellEditable(c, row);
        return (
          <TableCell
            key={c.id}
            align={columnAlign(c)}
            style={cl?.style}
            className={cn('whitespace-nowrap', cl?.style && 'overflow-hidden text-ellipsis', COLUMN_VARIANT_CLASSES[c.variant ?? 'default'], c.className, cl?.className, tint(cl))}
          >
            {editable ? (
              <EditableCell row={row} rowId={id} rowLabel={label} column={c} onCellEdit={onCellEdit} hintId={editHintId}>
                {content}
              </EditableCell>
            ) : (
              content
            )}
          </TableCell>
        );
      })}
      {rowActions && (
        <TableCell align="right" className={cn('w-12 py-0', layout?.trail.className, tint(layout?.trail))} style={layout?.trail.style}>
          <MoreMenu items={rowActions(row)} label={t('table.rowActions', { label })} variant="ghost" size="sm" />
        </TableCell>
      )}
    </TableRow>
  );
}

export const groupHeadClass = 'h-9 bg-secondary/50 text-[12.5px] font-semibold tracking-normal normal-case text-foreground';

export interface GroupHeaderRowProps<T> {
  group: DataTableBodyGroup<T>;
  open: boolean;
  selectable: boolean;
  selected: ReadonlySet<string>;
  /** Columns spanned by the header cell (every column but the selection one). */
  span: number;
  collapsible: boolean;
  onToggle?: (key: string) => void;
  onToggleRows?: (ids: readonly string[]) => void;
  ariaRowIndex?: number;
  style?: CSSProperties;
}

/** The header row of a group: group checkbox, collapse button, label and count. */
export function GroupHeaderRow<T>({ group, open, selectable, selected, span, collapsible, onToggle, onToggleRows, ariaRowIndex, style }: GroupHeaderRowProps<T>) {
  const { t } = useI18n();
  const state = selectionState(group.ids, selected);
  const count = group.ids.length;
  const heading = (
    <>
      <span className="truncate">{group.label}</span>{' '}
      <span className="rounded-full bg-secondary px-1.5 font-mono text-[11px] font-medium text-muted-foreground tabular-nums">{count}</span>{' '}
      <span className="sr-only">{count === 1 ? 'row' : 'rows'}</span>
    </>
  );
  return (
    <TableRow className="hover:bg-transparent" aria-rowindex={ariaRowIndex} style={style} data-group-header={group.key}>
      {selectable && (
        <TableCell className={cn('w-10 pe-0', groupHeadClass)}>
          <Checkbox
            aria-label={t('table.selectRow', { label: `all in ${group.name}` })}
            checked={state.checked}
            indeterminate={state.indeterminate}
            disabled={count === 0}
            onCheckedChange={() => onToggleRows?.(group.ids)}
          />
        </TableCell>
      )}
      <TableHead scope="rowgroup" colSpan={span} className={cn(groupHeadClass, collapsible && 'ps-2')}>
        {collapsible ? (
          <button
            type="button"
            aria-expanded={open}
            onClick={() => onToggle?.(group.key)}
            className="inline-flex max-w-full items-center gap-1.5 rounded-sm px-1 py-0.5 hover:bg-secondary focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring"
          >
            <ChevronRight
              size={14}
              aria-hidden
              className={cn('shrink-0 text-muted-foreground transition-transform motion-reduce:transition-none', open ? 'rotate-90' : 'rtl:-scale-x-100')}
            />
            {heading}
          </button>
        ) : (
          <span className="inline-flex max-w-full items-center gap-1.5">{heading}</span>
        )}
      </TableHead>
    </TableRow>
  );
}

import type { ReactNode } from 'react';

export type SortDirectionValue = 'ascending' | 'descending';
export type CellValue = string | number | boolean | Date | null | undefined;

export type DataTableColumnVariant = 'default' | 'mono' | 'muted' | 'numeric';

/** Body-cell classes of each column variant. */
export const COLUMN_VARIANT_CLASSES: Record<DataTableColumnVariant, string> = {
  default: '',
  mono: 'font-mono text-[12px]',
  muted: 'text-[12.5px] text-muted-foreground',
  numeric: 'font-mono text-[12.5px] tabular-nums',
};

/** Effective alignment of a column (numeric columns default to right). */
export function columnAlign<T>(column: DataTableColumn<T>): DataTableColumn<T>['align'] {
  return column.align ?? (column.variant === 'numeric' ? 'right' : undefined);
}

/** One typed column of a DataTable. */
export interface DataTableColumn<T> {
  /** Stable key (sorting, visibility). */
  id: string;
  /** Header text; also the column's name in the visibility menu. */
  header: string;
  /** Raw value: used to sort, and rendered when `cell` is absent. */
  accessor?: (row: T) => CellValue;
  /** Custom cell rendering. */
  cell?: (row: T) => ReactNode;
  sortable?: boolean;
  align?: 'left' | 'right' | 'center';
  /** Can be hidden from the column menu (default true). */
  hideable?: boolean;
  /** Hidden until turned on in the column menu. */
  defaultHidden?: boolean;
  /**
   * Presentational preset for the body cells: `mono` (monospace ids, regions), `muted`
   * (secondary text), `numeric` (monospace tabular figures, right-aligned unless `align` is set).
   */
  variant?: DataTableColumnVariant;
  /** Classes for the body cells (merged after the variant's). */
  className?: string;
  /** Classes for the header cell (e.g. a width). */
  headClassName?: string;

  /** Initial width in px (resizable or pinned tables; default 160). */
  width?: number;
  /** Smallest width a resize can reach (default 60). */
  minWidth?: number;
  /** Largest width a resize can reach (default 640). */
  maxWidth?: number;
  /** Shows a resize handle when the table is `resizable` (default true). */
  resizable?: boolean;
  /** Can be pinned from the column menu (default true). */
  pinnable?: boolean;

  /** Inline editing: Enter or F2 on the cell edits it (needs `onCellEdit` on the table). */
  editable?: boolean | ((row: T) => boolean);
  /** Editor of an editable cell (default a text input). */
  editor?: DataTableCellEditor;
  /** Value the editor starts from (default the accessor's value). */
  editValue?: (row: T) => string | number | null | undefined;
}

/** Editor of an editable column. */
export type DataTableCellEditor =
  | { type: 'text'; placeholder?: string }
  | { type: 'number'; min?: number; max?: number; step?: number }
  | { type: 'select'; options: ReadonlyArray<{ value: string; label: string }> };

export interface SortState {
  columnId: string;
  direction: SortDirectionValue;
}

/** Compares two cell values: nulls last, numbers and dates numerically, strings with localeCompare (numeric). */
export function compareValues(a: CellValue, b: CellValue): number {
  if (a == null && b == null) return 0;
  if (a == null) return 1;
  if (b == null) return -1;
  const na = a instanceof Date ? a.getTime() : a;
  const nb = b instanceof Date ? b.getTime() : b;
  if (typeof na === 'number' && typeof nb === 'number') return na - nb;
  if (typeof na === 'boolean' && typeof nb === 'boolean') return Number(na) - Number(nb);
  return String(na).localeCompare(String(nb), undefined, { numeric: true, sensitivity: 'base' });
}

/** Client-side sort (stable). Returns the input order when there is no sort or the column has no accessor. */
export function sortRows<T>(rows: readonly T[], columns: ReadonlyArray<DataTableColumn<T>>, sort: SortState | null): T[] {
  const column = sort ? columns.find((c) => c.id === sort.columnId) : undefined;
  if (!sort || !column?.accessor) return [...rows];
  const get = column.accessor;
  const sign = sort.direction === 'ascending' ? 1 : -1;
  return rows
    .map((row, index) => ({ row, index }))
    .sort((x, y) => {
      const va = get(x.row);
      const vb = get(y.row);
      // Nulls stay last in both directions.
      if (va == null || vb == null) return compareValues(va, vb) || x.index - y.index;
      return sign * compareValues(va, vb) || x.index - y.index;
    })
    .map(({ row }) => row);
}

/** Number of pages for a row count (at least 1). */
export function pageCountOf(total: number, pageSize: number): number {
  return Math.max(1, Math.ceil(total / Math.max(1, pageSize)));
}

/** Client-side pagination: the rows of a 1-based page (clamped to the valid range). */
export function paginate<T>(rows: readonly T[], page: number, pageSize: number): T[] {
  const last = pageCountOf(rows.length, pageSize);
  const p = Math.min(Math.max(1, page), last);
  return rows.slice((p - 1) * pageSize, p * pageSize);
}

/** Header checkbox state for the rows on screen. */
export function selectionState(visibleIds: readonly string[], selected: ReadonlySet<string>): { checked: boolean; indeterminate: boolean } {
  const count = visibleIds.filter((id) => selected.has(id)).length;
  return { checked: count > 0 && count === visibleIds.length, indeterminate: count > 0 && count < visibleIds.length };
}

/** Selects all of `ids` when not all are selected; otherwise clears them. Other selections are kept. */
export function toggleAll(ids: readonly string[], selected: ReadonlySet<string>): Set<string> {
  const next = new Set(selected);
  const all = ids.length > 0 && ids.every((id) => selected.has(id));
  for (const id of ids) {
    if (all) next.delete(id);
    else next.add(id);
  }
  return next;
}

export function toggleOne(id: string, selected: ReadonlySet<string>): Set<string> {
  const next = new Set(selected);
  if (next.has(id)) next.delete(id);
  else next.add(id);
  return next;
}

/** Default cell text for a raw value. */
export function formatCell(value: CellValue): ReactNode {
  if (value == null) return '—';
  if (value instanceof Date) return value.toLocaleDateString();
  if (typeof value === 'boolean') return value ? 'Yes' : 'No';
  return value;
}

/** Groups rows by a field key or by a function returning the group key. */
export type DataTableGroupBy<T> = Extract<keyof T, string> | ((row: T) => string | number | null | undefined);

/** One group of rows, in display order. */
export interface DataTableGroup<T> {
  /** Group key (`''` for rows without a value). */
  key: string;
  rows: T[];
}

/** Group key of a row (`''` when the value is null or undefined). */
export function groupKeyOf<T>(row: T, groupBy: DataTableGroupBy<T>): string {
  const value = typeof groupBy === 'function' ? groupBy(row) : (row as Record<string, unknown>)[groupBy];
  return value == null ? '' : String(value);
}

/**
 * Splits rows into groups, keeping the row order inside each group. Groups follow `order` (the
 * keys' first appearance in it, e.g. the unsorted input) and then any key not seen there.
 */
export function groupRows<T>(rows: readonly T[], groupBy: DataTableGroupBy<T>, order: readonly T[] = rows): DataTableGroup<T>[] {
  const groups = new Map<string, T[]>();
  for (const row of order) {
    const key = groupKeyOf(row, groupBy);
    if (!groups.has(key)) groups.set(key, []);
  }
  for (const row of rows) {
    const key = groupKeyOf(row, groupBy);
    const list = groups.get(key);
    if (list) list.push(row);
    else groups.set(key, [row]);
  }
  return [...groups].filter(([, list]) => list.length > 0).map(([key, list]) => ({ key, rows: list }));
}

import { Rows2, Rows3 } from '@gntik-ai/icons';
import { Toggle, ToggleGroup, type TableDensity, useI18n } from '@gntik-ai/ui';

