import { ArrowDown, ArrowUp, ChevronsUpDown } from '@gntik-ai/icons';
import { cn, nextSortDirection, TableHead, tableVariants, type SortDirection } from '@gntik-ai/ui';
import { stickyTint, type CellLayout } from './column-sizing';
import { columnAlign, type DataTableColumn } from './data-table-utils';
import { ColumnResizeHandle } from './resize-handle';

export interface DataTableHeadCellProps<T> {
  column: DataTableColumn<T>;
  sortDirection: SortDirection;
  onSortChange: (direction: Exclude<SortDirection, 'none'>) => void;
  layout?: CellLayout;
  /** Resize handle props; omitted, the column is not resizable. */
  resize?: { width: number; min: number; max: number; onResize: (width: number) => void };
}

/**
 * Column header of the DataTable. Without a resize handle it is the kit TableHead; with one, the
 * sort button and the handle sit side by side (the handle never nests inside the button).
 */
export function DataTableHeadCell<T>({ column, sortDirection, onSortChange, layout, resize }: DataTableHeadCellProps<T>) {
  const align = columnAlign(column);
  const pinnedClass = layout?.pinned ? cn(layout.className, 'z-[11]', stickyTint(layout, { head: true }), 'bg-card') : undefined;
  if (!resize) {
    return (
      <TableHead
        align={align}
        className={cn(column.headClassName, pinnedClass)}
        style={layout?.style}
        sortable={column.sortable}
        sortDirection={sortDirection}
        onSortChange={onSortChange}
        data-column-id={column.id}
      >
        {column.header}
      </TableHead>
    );
  }
  const v = tableVariants({ align: align ?? 'left', active: sortDirection !== 'none' });
  const SortIcon = sortDirection === 'ascending' ? ArrowUp : sortDirection === 'descending' ? ArrowDown : ChevronsUpDown;
  return (
    <TableHead
      align={align}
      className={cn('relative overflow-visible', column.headClassName, pinnedClass)}
      style={layout?.style}
      aria-sort={column.sortable ? sortDirection : undefined}
      data-column-id={column.id}
    >
      <span className={cn('block min-w-0 truncate pe-2', align === 'right' && 'text-end', align === 'center' && 'text-center')}>
        {column.sortable ? (
          <button type="button" className={cn(v.sortButton(), 'max-w-full')} onClick={() => onSortChange(nextSortDirection(sortDirection))}>
            <span className="truncate">{column.header}</span>
            <SortIcon size={13} aria-hidden className={sortDirection === 'none' ? 'opacity-40' : undefined} />
          </button>
        ) : (
          column.header
        )}
      </span>
      <ColumnResizeHandle label={column.header} width={resize.width} min={resize.min} max={resize.max} onResize={resize.onResize} />
    </TableHead>
  );
}

import { cn } from '@gntik-ai/ui';
import { useRef, type KeyboardEvent, type PointerEvent } from 'react';

export interface ColumnResizeHandleProps {
  /** Column name for the accessible label ("Resize Region column"). */
  label: string;
  width: number;
  min: number;
  max: number;
  onResize: (width: number) => void;
  /** Called once a drag or a key press ends a resize. */
  onResizeEnd?: (width: number) => void;
}

const STEP = 10;
const BIG_STEP = 50;

/**
 * Column resize handle at the end edge of a header cell: a focusable `role="separator"` with
 * aria-valuenow/min/max (the width in px). Drag it with a pointer; from the keyboard,
 * ArrowLeft/ArrowRight change the width by 10px (Shift: 50px), Home/End jump to the limits.
 */
export function ColumnResizeHandle({ label, width, min, max, onResize, onResizeEnd }: ColumnResizeHandleProps) {
  const drag = useRef<{ x: number; width: number; dir: 1 | -1 } | null>(null);
  const clamp = (w: number) => Math.round(Math.min(max, Math.max(min, w)));

  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    e.currentTarget.setPointerCapture?.(e.pointerId);
    const rtl = typeof getComputedStyle === 'function' && getComputedStyle(e.currentTarget).direction === 'rtl';
    drag.current = { x: e.clientX, width, dir: rtl ? -1 : 1 };
  };
  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d) return;
    onResize(clamp(d.width + (e.clientX - d.x) * d.dir));
  };
  const onPointerUp = (e: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    drag.current = null;
    if (d) onResizeEnd?.(clamp(d.width + (e.clientX - d.x) * d.dir));
  };
  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const step = e.shiftKey ? BIG_STEP : STEP;
    const rtl = typeof getComputedStyle === 'function' && getComputedStyle(e.currentTarget).direction === 'rtl';
    const grow = rtl ? 'ArrowLeft' : 'ArrowRight';
    const shrink = rtl ? 'ArrowRight' : 'ArrowLeft';
    let next: number | null = null;
    if (e.key === grow || e.key === 'ArrowUp') next = width + step;
    else if (e.key === shrink || e.key === 'ArrowDown') next = width - step;
    else if (e.key === 'Home') next = min;
    else if (e.key === 'End') next = max;
    if (next == null) return;
    e.preventDefault();
    const w = clamp(next);
    onResize(w);
    onResizeEnd?.(w);
  };

  return (
    <div
      role="separator"
      tabIndex={0}
      aria-orientation="vertical"
      aria-label={`Resize ${label} column`}
      aria-valuenow={width}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuetext={`${width} pixels`}
      data-column-resizer=""
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      onKeyDown={onKeyDown}
      className={cn(
        'group/resizer absolute inset-y-0 -end-1.5 z-[2] flex w-3 cursor-col-resize touch-none justify-center',
        'focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-focus-ring',
      )}
    >
      <span
        aria-hidden
        className="my-2 w-px bg-border transition-colors group-hover/resizer:w-0.5 group-hover/resizer:bg-primary group-focus-visible/resizer:w-0.5 group-focus-visible/resizer:bg-primary motion-reduce:transition-none"
      />
    </div>
  );
}

import { useState } from 'react';
import { newViewId, sameViewState, type DataTableView, type DataTableViewState } from './views';

/** A value that is controlled when `value` is defined, otherwise kept in state. */
export function useControllable<V>(value: V | undefined, initial: V | (() => V), onChange?: (next: V) => void): [V, (next: V) => void] {
  const [inner, setInner] = useState<V>(initial);
  const current = value === undefined ? inner : value;
  const set = (next: V) => {
    setInner(next);
    onChange?.(next);
  };
  return [current, set];
}

export interface UseTableViewsOptions {
  views?: readonly DataTableView[];
  defaultViews?: readonly DataTableView[];
  onViewsChange?: (views: DataTableView[]) => void;
  activeViewId?: string | null;
  defaultActiveViewId?: string | null;
  onActiveViewChange?: (id: string | null) => void;
  /** The table's state right now. */
  current: DataTableViewState;
  /** The table's state with no view applied (props' defaults). */
  defaults: DataTableViewState;
  /** Applies a complete state to the table. */
  apply: (state: DataTableViewState) => void;
}

/** Saved-views state machine for the DataTable: select, save as, save, rename, delete, reset. */
export function useTableViews({ views: viewsProp, defaultViews = [], onViewsChange, activeViewId, defaultActiveViewId = null, onActiveViewChange, current, defaults, apply }: UseTableViewsOptions) {
  const [views, setViews] = useControllable<readonly DataTableView[]>(viewsProp, defaultViews, (next) => onViewsChange?.([...next]));
  const [activeId, setActiveId] = useControllable<string | null>(activeViewId, defaultActiveViewId, onActiveViewChange);
  const active = views.find((v) => v.id === activeId) ?? null;
  const target = (view: DataTableView | null): DataTableViewState => ({ ...defaults, ...(view?.state ?? {}) });
  const dirty = !sameViewState(current, target(active));

  return {
    views,
    activeId: active ? active.id : null,
    dirty,
    select: (id: string | null) => {
      const view = views.find((v) => v.id === id) ?? null;
      setActiveId(view ? view.id : null);
      apply(target(view));
    },
    saveAs: (name: string) => {
      const view: DataTableView = { id: newViewId(name, views), name, state: current };
      setViews([...views, view]);
      setActiveId(view.id);
    },
    save: () => {
      if (!active) return;
      setViews(views.map((v) => (v.id === active.id ? { ...v, state: current } : v)));
    },
    rename: (id: string, name: string) => setViews(views.map((v) => (v.id === id ? { ...v, name } : v))),
    remove: (id: string) => {
      setViews(views.filter((v) => v.id !== id));
      if (id === activeId) setActiveId(null);
    },
    reset: () => apply(target(active)),
  };
}

import { useEffect, useState, type RefObject } from 'react';

/** The items to render: `[start, end)` of the flattened body, each `rowHeight` px tall. */
export interface VirtualWindow {
  start: number;
  end: number;
  rowHeight: number;
}

export interface UseVirtualRowsOptions {
  enabled: boolean;
  count: number;
  rowHeight: number;
  /** The `<table>`; its parent is the scroll container. */
  tableRef: RefObject<HTMLTableElement | null>;
  /** Fallback viewport height before the container is measured (and in jsdom). */
  viewportHeight: number;
  /** Extra rows rendered above and below the viewport. */
  overscan?: number;
}

/** Computes a virtual window from the table container's scroll position. */
export function windowFor(count: number, scrollTop: number, viewport: number, rowHeight: number, overscan: number): VirtualWindow {
  const h = Math.max(1, rowHeight);
  const first = Math.floor(Math.max(0, scrollTop) / h);
  const visible = Math.ceil(viewport / h) + 1;
  const start = Math.max(0, Math.min(count, first - overscan));
  const end = Math.max(start, Math.min(count, first + visible + overscan));
  return { start, end, rowHeight: h };
}

/**
 * Row virtualization for the DataTable: listens to the scroll container of the table and returns
 * the window of items to render, or `undefined` when disabled.
 */
export function useVirtualRows({ enabled, count, rowHeight, tableRef, viewportHeight, overscan = 8 }: UseVirtualRowsOptions): VirtualWindow | undefined {
  const [scroll, setScroll] = useState({ top: 0, height: viewportHeight });

  useEffect(() => {
    const el = tableRef.current?.parentElement;
    if (!enabled || !el) return undefined;
    let frame = 0;
    const read = () => {
      frame = 0;
      setScroll((prev) => {
        const height = el.clientHeight || prev.height;
        return prev.top === el.scrollTop && prev.height === height ? prev : { top: el.scrollTop, height };
      });
    };
    const schedule = () => {
      if (frame) return;
      frame = typeof requestAnimationFrame === 'function' ? requestAnimationFrame(read) : (setTimeout(read, 0) as unknown as number);
    };
    el.addEventListener('scroll', schedule, { passive: true });
    const ro = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(schedule);
    ro?.observe(el);
    schedule();
    return () => {
      el.removeEventListener('scroll', schedule);
      ro?.disconnect();
      if (frame && typeof cancelAnimationFrame === 'function') cancelAnimationFrame(frame);
    };
  }, [enabled, tableRef]);

  if (!enabled) return undefined;
  return windowFor(count, scroll.top, scroll.height, rowHeight, overscan);
}

import { Bookmark, ChevronDown } from '@gntik-ai/icons';
import {
  Button,
  Dialog,
  DialogBody,
  DialogClose,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  Input,
  Menu,
  MenuContent,
  MenuGroup,
  MenuGroupLabel,
  MenuItem,
  MenuRadioGroup,
  MenuRadioItem,
  MenuSeparator,
  MenuTrigger,
} from '@gntik-ai/ui';
import { useId, useState } from 'react';
import type { ColumnWidths, PinnedColumns } from './column-sizing';
import type { SortState } from './data-table-utils';

/** What a saved view captures. Every field is optional: a missing field keeps the table's default. */
export interface DataTableViewState {
  /** Opaque filter state of the page's toolbar (see the table's `filters` / `onFiltersChange`). */
  filters?: unknown;
  sort?: SortState | null;
  hiddenColumns?: readonly string[];
  columnWidths?: ColumnWidths;
  pinnedColumns?: PinnedColumns;
  /** A field key, or `null` for no grouping (function `groupBy`s cannot be saved). */
  groupBy?: string | null;
}

export interface DataTableView {
  id: string;
  name: string;
  state: DataTableViewState;
}

const norm = (s: DataTableViewState) =>
  JSON.stringify({
    filters: s.filters ?? null,
    sort: s.sort ?? null,
    hiddenColumns: [...(s.hiddenColumns ?? [])].sort(),
    columnWidths: Object.fromEntries(Object.entries(s.columnWidths ?? {}).sort(([a], [b]) => a.localeCompare(b))),
    pinnedColumns: { left: s.pinnedColumns?.left ?? [], right: s.pinnedColumns?.right ?? [] },
    groupBy: s.groupBy ?? null,
  });

/** Whether two view states are equivalent (key order and empty values ignored). */
export function sameViewState(a: DataTableViewState, b: DataTableViewState): boolean {
  return norm(a) === norm(b);
}

/** A new view id that does not collide with `views`. */
export function newViewId(name: string, views: readonly DataTableView[]): string {
  const base = name.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'view';
  let id = base;
  for (let i = 2; views.some((v) => v.id === id); i++) id = `${base}-${i}`;
  return id;
}

export interface ViewSwitcherProps {
  views: readonly DataTableView[];
  activeId: string | null;
  /** The table differs from the active view (or from the defaults when none is active). */
  dirty: boolean;
  onSelect: (id: string | null) => void;
  onSaveAs: (name: string) => void;
  onSave: () => void;
  onRename: (id: string, name: string) => void;
  onDelete: (id: string) => void;
  onReset: () => void;
}

const DEFAULT_VALUE = '__default__';

/** "Views" menu: switch between saved views, save the current table as a view, rename, delete, reset. */
export function ViewSwitcher({ views, activeId, dirty, onSelect, onSaveAs, onSave, onRename, onDelete, onReset }: ViewSwitcherProps) {
  const inputId = useId();
  const active = views.find((v) => v.id === activeId) ?? null;
  const [dialog, setDialog] = useState<'create' | 'rename' | null>(null);
  const [name, setName] = useState('');
  const open = (mode: 'create' | 'rename') => {
    setName(mode === 'rename' && active ? active.name : '');
    setDialog(mode);
  };
  const submit = () => {
    const trimmed = name.trim();
    if (!trimmed) return;
    if (dialog === 'rename' && active) onRename(active.id, trimmed);
    else onSaveAs(trimmed);
    setDialog(null);
  };
  return (
    <>
      <Menu>
        <MenuTrigger render={<Button variant="secondary" size="sm" icon={Bookmark} trailingIcon={ChevronDown} />}>
          <span className="max-w-40 truncate">{active ? active.name : 'Default view'}</span>
          {dirty && (
            <>
              {' '}
              <span aria-hidden className="size-1.5 rounded-full bg-primary" /> <span className="sr-only">(modified)</span>
            </>
          )}
        </MenuTrigger>
        <MenuContent align="end" className="min-w-[220px]">
          <MenuGroup>
            <MenuGroupLabel>Views</MenuGroupLabel>
            <MenuRadioGroup value={activeId ?? DEFAULT_VALUE} onValueChange={(v: unknown) => onSelect(v === DEFAULT_VALUE ? null : String(v))}>
              <MenuRadioItem value={DEFAULT_VALUE}>Default view</MenuRadioItem>
              {views.map((v) => (
                <MenuRadioItem key={v.id} value={v.id}>
                  {v.name}
                </MenuRadioItem>
              ))}
            </MenuRadioGroup>
          </MenuGroup>
          <MenuSeparator />
          <MenuItem disabled={!active || !dirty} onClick={onSave}>
            Save changes
          </MenuItem>
          <MenuItem onClick={() => open('create')}>Save as new view…</MenuItem>
          <MenuItem disabled={!active} onClick={() => open('rename')}>
            Rename view…
          </MenuItem>
          <MenuItem disabled={!active} onClick={() => active && onDelete(active.id)}>
            Delete view
          </MenuItem>
          <MenuItem disabled={!dirty} onClick={onReset}>
            Reset changes
          </MenuItem>
        </MenuContent>
      </Menu>
      <Dialog open={dialog != null} onOpenChange={(o) => !o && setDialog(null)}>
        <DialogContent size="sm">
          <form
            onSubmit={(e) => {
              e.preventDefault();
              submit();
            }}
          >
            <DialogHeader>
              <DialogTitle>{dialog === 'rename' ? 'Rename view' : 'Save view'}</DialogTitle>
            </DialogHeader>
            <DialogBody>
              <label htmlFor={inputId} className="mb-1.5 block text-[12.5px] font-medium text-foreground">
                View name
              </label>
              <Input id={inputId} value={name} onChange={(e) => setName(e.target.value)} autoComplete="off" required />
            </DialogBody>
            <DialogFooter>
              <DialogClose render={<Button variant="ghost" />}>Cancel</DialogClose>
              <Button type="submit" disabled={!name.trim()}>
                {dialog === 'rename' ? 'Rename' : 'Save view'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </>
  );
}
